	@Test
	void readFixtureAbortsItsNativeSnapshotBeforeClosingTheEnvironment() throws Exception {
		LmdbPersistentAdjacencyBenchmark.ReadState state = new LmdbPersistentAdjacencyBenchmark.ReadState();
		state.statementCount = 256;
		List<String> ownershipEvents = new ArrayList<>();
		boolean teardownAttempted = false;
		try {
			state.setup();
			long snapshot = state.snapshot.get();
			long environment = state.fixture.environment;
			try (MockedStatic<LMDB> ignored = mockStatic(LMDB.class, invocation -> {
				String method = invocation.getMethod().getName();
				if (method.equals("mdb_txn_abort")) {
					long transaction = invocation.getArgument(0);
					if (transaction == snapshot) {
						ownershipEvents.add("abort snapshot");
					}
				} else if (method.equals("mdb_env_close")) {
					long closing = invocation.getArgument(0);
					if (closing == environment) {
						ownershipEvents.add("close environment");
					}
				}
				return invocation.callRealMethod();
			})) {
				teardownAttempted = true;
				state.teardown();
			}
			assertThat(ownershipEvents).containsExactly("abort snapshot", "close environment");
		} finally {
			if (!teardownAttempted) {
				state.teardown();
			}
		}
	}

